#include "Frontend.h"
#include <cstdlib>
#include <iostream>
using namespace jspp;static void check(bool x,const char*m){if(!x){std::cerr<<m<<'\n';std::exit(1);}}
int main(){Program p;Diagnostic d;check(parse_source("const x=1+2*3; x>=7;",p,d),"valid source rejected");check(p.statements.size()==2,"statement count");check(p.statements[0].expression->kind==ExprKind::Binary,"expression tree missing");Program flow;check(parse_source("let x=0;for(let i=0;i<3;i=i+1){if(i===1)continue;x=x+i;}while(x<5){x=x+1;if(x===4)break;}x?x:9;",flow,d),"control flow rejected");check(flow.statements.size()==4&&flow.statements[1].kind==StatementKind::For&&flow.statements[2].kind==StatementKind::While,"control-flow tree missing");Program functions;check(parse_source("function add(a,b){return a+b;}const twice=x=>x*2;twice(add(1,2));",functions,d),"functions rejected");check(functions.statements[0].kind==StatementKind::FunctionDeclaration&&functions.statements[0].expression->parameters.size()==2,"function tree missing");Program bad;check(!parse_source("let = 1",bad,d)&&d.line==1&&d.column==5,"bad binding accepted");Program eof;check(!parse_source("(1+2",eof,d),"missing delimiter accepted");Program unsupported;check(!parse_source("switch(x){}",unsupported,d),"unsupported statement accepted");std::cout<<"JS++ frontend passed\n";}
